// ============================================================
// Monta o e-mail do contato recebido pelo site.
//
// Valida antes de enviar: formulário público sem validação vira porta
// de spam, e cada mensagem falsa custa a sua atenção — que é o recurso
// mais escasso enquanto a operação é pequena.
// ============================================================

const raw = $input.first().json;
const b = raw.body || raw;

const limpo = (v, max) => String(v ?? '').trim().slice(0, max);
const esc = t => String(t ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const nome = limpo(b.nome, 120);
const email = limpo(b.email, 160);
const telefone = limpo(b.telefone, 40);
const empresa = limpo(b.empresa, 160);
const mensagem = limpo(b.mensagem, 4000);

// Rejeita o óbvio. Não é antispam de verdade — é o filtro que evita as
// tentativas automáticas mais grosseiras sem atrapalhar ninguém real.
const emailValido = /^[^@\s]+@[^@\s]+\.[^@\s]{2,}$/.test(email);
if (!nome || !emailValido || !mensagem) {
  return [{ json: { valido: false, motivo: 'campos obrigatórios ausentes ou e-mail inválido' } }];
}

const quando = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

const html = `<!DOCTYPE html><html lang='pt-BR'><head><meta charset='utf-8'></head>
<body style='margin:0;padding:20px;background:#F1F5F9;font-family:Inter,Arial,Helvetica,sans-serif;'>
<table role='presentation' width='560' cellpadding='0' cellspacing='0' style='max-width:560px;background:#FFFFFF;border-radius:12px;overflow:hidden;'>
  <tr><td style='background:#0B1E3B;padding:18px 22px;color:#FFFFFF;font-size:15px;font-weight:800;'>Contato pelo site</td></tr>
  <tr><td style='padding:18px 22px;'>
    <div style='font-size:17px;font-weight:800;color:#0B1E3B;'>${esc(nome)}</div>
    <div style='font-size:12.5px;color:#64748B;margin:2px 0 16px;'>${esc(empresa || 'empresa não informada')} &middot; ${esc(quando)}</div>

    <table role='presentation' width='100%' cellpadding='0' cellspacing='0' style='font-size:13px;border-collapse:collapse;'>
      <tr><td style='padding:6px 0;color:#64748B;width:90px;'>E-mail</td><td style='padding:6px 0;color:#0B1E3B;font-weight:600;'><a href='mailto:${esc(email)}' style='color:#059669;'>${esc(email)}</a></td></tr>
      <tr><td style='padding:6px 0;color:#64748B;'>Telefone</td><td style='padding:6px 0;color:#0B1E3B;font-weight:600;'>${esc(telefone || '—')}</td></tr>
    </table>

    <div style='margin-top:18px;padding:14px 16px;background:#F8FAFC;border-left:3px solid #0B1E3B;border-radius:6px;color:#334155;font-size:14px;line-height:1.7;white-space:pre-wrap;'>${esc(mensagem)}</div>

    <div style='margin-top:18px;'>
      <a href='mailto:${esc(email)}' style='display:inline-block;background:#0B1E3B;color:#FFFFFF;font-size:13px;font-weight:800;padding:11px 22px;border-radius:8px;text-decoration:none;'>Responder</a>
    </div>
  </td></tr>
</table></body></html>`;

return [{
  json: {
    valido: true,
    email_contato: email,
    assunto: `[Site] ${nome}${empresa ? ' — ' + empresa : ''}`,
    html
  }
}];
